payout:
const terms = ctx.subject.employment.terms;
const basic = ctx.month_wage;
if (get(terms, 'rate.unit', 'MONTHLY') !== 'MONTHLY' || !(basic > 0)) return ctx.day_rate * ctx.entry.quantity;
// MOM gross rate of pay for salary in lieu of annual leave: the basic day with the fixed allowance on it
const allowance = get(terms, 'allowances.FIXED_MONTHLY.amount', 0);
const fixed = typeof allowance === 'number' ? allowance : get(allowance, 'value', 0);
return ctx.day_rate * ((basic + fixed) / basic) * ctx.entry.quantity;

lookup.entitlement:
// CDCSA s.12B, EA s.87A (MOM, Childcare leave): 6 days a year while a child is under 7 in the year,
// else 2 days of extended childcare leave while the youngest is 7 to 12; from 3 months' service,
// a first year prorated by completed months (service_bands), never below the 2 days the EA gives.
const employment = ctx.subject.employment;
const yearStart = String(ctx.as_of).slice(0, 4) + '-01-01';
const ages = get(employment, 'family', [])
	.filter((member) => member.relation === 'CHILD' && get(member, 'born_on', null) != null && member.born_on <= ctx.as_of)
	.map((member) => (member.born_on > yearStart ? 0 : age_on(member.born_on, yearStart)));
const youngest = ages.length === 0 ? null : Math.min(...ages);
if (youngest === null || youngest > 12) return 0;
const start = get(employment, 'service_started_on', get(employment, 'effective_range.from', ctx.as_of));
const months = calendar_completed_months(start, ctx.as_of);
const bands = ctx.lookup.service_bands.filter((band) => band.service_months <= months);
if (bands.length === 0) return 0;
const full = youngest < ctx.lookup.child_age_limit_years ? 6 : 2;
return Math.min(full, Math.max(2, bands[bands.length - 1].days));

// Child leave is a shared pool: 10 weeks from 1 April 2026, 6 weeks before. Each parent defaults to half;
// an HR-approved transfer is the child's own allocation under the leave catalogue code.
const birth = String(get(ctx, 'event.on', ctx.as_of));
const allocated = get(get(ctx.subject.employment, 'family', []).find((member) => member.relation === 'CHILD' && get(member, 'born_on', null) === birth), 'allocations.SHARED_PARENTAL_LEAVE', null);
if (allocated != null) return Number(allocated);
return (birth >= '2026-04-01' ? 70 : 42) / 2;

// Employment (Part-Time Employees) Regulations reg.7(1): the similar full-time annual leave under EA s.88A in proportion to the part-timer's weekly hours; reg.2(2) deems that employee to work 8 hours a day and 44 hours a week.
const employment = ctx.subject.employment;
const terms = get(employment, 'terms', {});
const weekly = Number(get(terms, 'normal_hours_per_week', 0));
const stated = Number(get(terms, 'normal_hours_per_day', 0));
const daysPerWeek = Number(get(terms, 'normal_days_per_week', 0));
const day = stated > 0 ? stated : daysPerWeek > 0 ? weekly / daysPerWeek : 0;
if (!(weekly > 0) || !(day > 0)) return 0;
const start = get(employment, 'service_started_on', get(employment, 'effective_range.from', ctx.as_of));
const months = calendar_completed_months(start, ctx.as_of);
if (months < ctx.lookup.eligibility_months) return 0;
const bands = ctx.lookup.service_bands;
const firstBand = bands[0];
const at = bands.filter((band) => band.service_months <= months);
let full = 0;
if (months < firstBand.service_months) full = (ctx.lookup.first_year_days * calendar_completed_months(start, add_days(ctx.as_of, 1))) / firstBand.service_months;
else if (at.length > 0) full = at[at.length - 1].days;
if (!(full > 0)) return 0;
// reg.2(2): the similar full-time employee's own hours; 8 a day and 44 a week only where there is none
const facts = get(employment, 'employee_extension_data', {});
const fullWeek = Number(get(facts, 'comparable_full_time_hours_per_week', ctx.lookup.full_time_weekly_hours));
const fullDay = Number(
	get(facts, 'comparable_full_time_hours_per_day', ctx.lookup.full_time_weekly_hours / ctx.lookup.full_time_days_per_week)
);
return Math.ceil(full * (weekly / fullWeek) * (fullDay / day) * 2) / 2;

