paid_share:
// WICA 2019 First Schedule para.4(1): full average monthly earnings for up to 14 days of outpatient medical leave, two-thirds from day 15, to one year from the accident.
if (ctx.event != null && calendar_completed_months(ctx.event.on, ctx.as_of) >= ctx.lookup.max_months) return 0;
return ctx.used < ctx.lookup.days ? 1 : 2 / 3;

// WICA 2019 First Schedule para.4(1): full average monthly earnings for up to 60 days of hospitalisation leave, two-thirds from day 61, to one year from the accident.
if (ctx.event != null && calendar_completed_months(ctx.event.on, ctx.as_of) >= ctx.lookup.max_months) return 0;
return ctx.used < ctx.lookup.days ? 1 : 2 / 3;
